import React, { useEffect, useRef, useState } from "react";
import { motion, useInView } from "framer-motion";
import { STATS } from "../types";
import { Award, Users, Globe, Heart } from "lucide-react";

function Counter({ to, suffix, index }: { to: number; suffix: string; index: number }) {
  const [val, setVal] = useState(0);
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-50px" });

  useEffect(() => {
    if (isInView) {
      const duration = 2000;
      const start = performance.now();
      const tick = (now: number) => {
        const p = Math.min(1, (now - start) / duration);
        const eased = 1 - Math.pow(1 - p, 3);
        setVal(Math.round(to * eased));
        if (p < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    }
  }, [isInView, to]);

  return (
    <motion.span
      ref={ref}
      className="block text-5xl md:text-6xl font-bold text-amber-400"
      style={{ fontFamily: "Georgia, serif" }}
      initial={{ opacity: 0, scale: 0.5 }}
      animate={isInView ? { opacity: 1, scale: 1 } : {}}
      transition={{ delay: index * 0.1, duration: 0.5 }}
    >
      {val.toLocaleString()}{suffix}
    </motion.span>
  );
}

const values = [
  { icon: Award, title: "Premium Quality", desc: "Every roll inspected" },
  { icon: Users, title: "350+ Decorators", desc: "Trust our products" },
  { icon: Globe, title: "240+ Cities", desc: "Pan India reach" },
  { icon: Heart, title: "12+ Years", desc: "Of excellence" },
];

export default function About() {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-100px" });

  return (
    <section id="about" className="py-24 lg:py-32 bg-gradient-to-b from-amber-50 to-white">
      <div className="container mx-auto px-6">
        <div className="grid lg:grid-cols-2 gap-16 items-center">
          {/* Left - Content */}
          <motion.div
            initial={{ opacity: 0, x: -50 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8 }}
          >
            <motion.div className="flex items-center gap-4 mb-6" initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }}>
              <div className="h-px w-12 bg-gradient-to-r from-transparent to-amber-400" />
              <span className="text-sm font-semibold tracking-[0.15em] uppercase text-amber-500">About Us</span>
            </motion.div>

            <motion.h2
              className="text-4xl md:text-5xl font-bold text-gray-900 mb-6 leading-tight"
              style={{ fontFamily: "Georgia, serif" }}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: 0.1 }}
            >
              A fabric house from Ludhiana, adorning India&apos;s grandest{" "}
              <span className="text-amber-500">celebrations</span>.
            </motion.h2>

            <motion.p
              className="text-lg text-gray-600 mb-6 leading-relaxed"
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: 0.2 }}
            >
              For over a decade, D SAJAWAT has been the quiet hand behind some of the country&apos;s most exquisite wedding venues. We source, finish and supply premium fabrics - drapes, covers, sashes, florals.
            </motion.p>

            <motion.p
              className="text-lg text-gray-600 leading-relaxed"
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ delay: 0.3 }}
            >
              From a single roll to a banquet&apos;s worth - we deliver across India, on time, in finish.
            </motion.p>

            {/* Values Grid */}
            <div className="grid grid-cols-2 gap-6 mt-10">
              {values.map((item, i) => (
                <motion.div
                  key={item.title}
                  className="flex items-start gap-4 p-4 rounded-2xl bg-white shadow-lg shadow-gray-100"
                  initial={{ opacity: 0, y: 30 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ delay: 0.3 + i * 0.1 }}
                  whileHover={{ y: -4, boxShadow: "0 20px 40px rgba(0,0,0,0.1)" }}
                >
                  <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-amber-100 to-amber-200 flex items-center justify-center flex-shrink-0">
                    <item.icon size={24} className="text-amber-600" />
                  </div>
                  <div>
                    <h4 className="font-semibold text-gray-900">{item.title}</h4>
                    <p className="text-sm text-gray-500">{item.desc}</p>
                  </div>
                </motion.div>
              ))}
            </div>
          </motion.div>

          {/* Right - Stats */}
          <motion.div
            ref={ref}
            className="grid grid-cols-2 gap-6"
            initial={{ opacity: 0, x: 50 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.8, delay: 0.2 }}
          >
            {STATS.map((stat, i) => (
              <motion.div
                key={stat.label}
                className="bg-white rounded-3xl p-8 shadow-xl shadow-gray-200/50 text-center"
                initial={{ opacity: 0, y: 40 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: 0.2 + i * 0.1 }}
                whileHover={{ y: -8, boxShadow: "0 25px 50px rgba(0,0,0,0.15)" }}
              >
                <Counter to={stat.value} suffix={stat.suffix} index={i} />
                <span className="block mt-3 text-sm font-medium text-gray-500 uppercase tracking-wider">{stat.label}</span>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </div>
    </section>
  );
}
